// Returns true iff `v` starts with prefix `p`.
// Definition: true if `p` is empty, or if `v` has length at least `p.len()`
// and all characters match in the first `p.len()` positions.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

// Filters `xs`, keeping exactly those sequences that start with prefix `p`.
// The relative order of kept sequences is preserved.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered: Vec<Vec<char>> = Vec::new();
    for v in xs {
        if has_prefix(&v, &p) {
            filtered.push(v);
        }
    }
    filtered
}